<?php if($notice):?><p class="notice" role="status"><?=e($notice)?></p><?php endif;?>
<section class="pub-card" aria-labelledby="search-schedule-title"><h2 id="search-schedule-title">Review schedule</h2>
<p>Uses only the owner’s existing confirmed Search Console property. Reviews make no page edits, indexing requests, social posts or email sends.</p>
<?php if($target??null):?><p><strong>Account:</strong> <?=e($target['account'])?> · <strong>Property:</strong> <?=e($target['property'])?></p><?php else:?><p>Connect and confirm your Search Console property before enabling scheduled reviews.</p><?php endif;?>
<form data-no-form-assist method="post"><?=csrf_field()?><input type="hidden" name="connection" value="<?=e($target['fingerprint']??'')?>"><input type="hidden" name="action" value="save"><input type="hidden" name="version" value="<?=(int)$schedule['version']?>">
<div class="google-grid"><label>Reporting window<select name="days"><option value="28" <?=$schedule['days']===28?'selected':''?>>28 complete days</option><option value="90" <?=$schedule['days']===90?'selected':''?>>90 complete days</option></select></label>
<label>Frequency<select name="cadence"><option value="weekly" <?=$schedule['cadence']==='weekly'?'selected':''?>>Every seven days</option><option value="daily" <?=$schedule['cadence']==='daily'?'selected':''?>>Every 24 hours</option></select></label></div>
<p><label class="google-check"><input type="checkbox" name="enabled" value="1" <?=!empty($schedule['enabled'])?'checked':''?>> Enable scheduled reviews</label></p>
<p><label class="google-check"><input type="checkbox" name="consent" value="1"> I allow scheduled reads of my currently selected Search Console property and private storage of up to six review summaries.</label></p>
<button class="wbtn primary">Save review preferences</button></form>
<p>Saving starts the next interval; it does not read Google immediately. Disable and save to delete saved summaries and cancel pending results. A changed account, property or application requires a new reviewed opt-in.</p>
<dl><dt>Schedule</dt><dd><?=!empty($schedule['enabled'])&&$connectionMatches?'Enabled':'Paused / connection review needed'?></dd><dt>Last attempt</dt><dd><?=empty($schedule['attempted_at'])?'Not yet recorded':e(date('j M Y H:i T',(int)$schedule['attempted_at']))?></dd><dt>Latest outcome</dt><dd><?=e(['disabled'=>'Disabled','scheduled'=>'Waiting for next interval','reading'=>'Read in progress','completed'=>'Review saved','review_failed'=>'Read failed; previous report retained','connection_changed'=>'Connection changed; opt in again'][$schedule['state']]??'Review needed')?></dd><dt>Next scheduled attempt</dt><dd><?=!empty($schedule['enabled'])&&$connectionMatches&&!empty($schedule['next_at'])?e(date('j M Y H:i T',(int)$schedule['next_at'])):'Not scheduled'?></dd></dl>
<?php if(!empty($schedule['enabled'])&&$connectionMatches):?><form data-no-form-assist method="post"><?=csrf_field()?><input type="hidden" name="action" value="read"><button class="wbtn">Read and save a review now</button><p>One read per hour at most. The selected window is compared with the preceding equal window, ending three days ago.</p></form><?php endif;?>
</section>
<section class="pub-card" aria-labelledby="saved-search-title"><h2 id="saved-search-title">Saved review summaries</h2>
<?php if(!$reports):?><p>No saved review is available for this schedule and connection. Enable the schedule or explicitly request a review after setup.</p><?php endif;?>
<?php foreach($reports as$report):?><article class="google-search-review"><h3><?=e($report['current']['start'].' – '.$report['current']['end'])?></h3><p>Compared with <?=e($report['previous']['start'].' – '.$report['previous']['end'])?> · Observed <?=e($report['observed_at'])?></p>
<p><?=(int)$report['current_sample']?> eligible current rows; <?=(int)$report['previous_sample']?> previous rows. These are samples, not complete site totals.</p>
<?php if(!$report['rows']):?><p>No review signals found in the returned sample. This does not certify that search performance has no issues.</p><?php else:?><div class="pub-table-wrap" tabindex="0" role="region" aria-label="Search opportunities, scroll horizontally"><table class="pub-table"><caption>Pages to review</caption><thead><tr><th scope="col">Page</th><th scope="col">Signal</th><th scope="col">Clicks now / before</th><th scope="col">Next step</th></tr></thead><tbody><?php foreach($report['rows']as$item):?><tr><th scope="row"><a href="<?=e($item['page'])?>" target="_blank" rel="noopener noreferrer"><?=e($item['page'])?></a></th><td><?=e($item['signal'])?></td><td><?=e((string)$item['clicks'])?> / <?=$item['prior_clicks']===null?'Unavailable':e((string)$item['prior_clicks'])?></td><td><?=e($item['reason'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<p><?=e($report['note'])?></p></article><?php endforeach;?></section>
</main>
